const MAGIC = 516114522;

/** Small valid-looking EPA SWMM 5.x binary fixture matching published layout.
 * This is NOT a file generated by EPA SWMM. Regression against real SWMM files
 * is required before production use.
 */
export function createOut(nPeriods = 3) {
  const nSubcatch = 1, nNodes = 2, nLinks = 1, nPollutants = 0;
  const encoder = new TextEncoder();
  const u8 = new Uint8Array(28 + 4 * 1024 + nPeriods * 200 + 24);
  const view = new DataView(u8.buffer);
  let pos = 0;
  const i32 = value => { view.setInt32(pos, value, true); pos += 4; };
  const f32 = value => { view.setFloat32(pos, value, true); pos += 4; };
  const f64 = value => { view.setFloat64(pos, value, true); pos += 8; };
  const string = value => { const bytes = encoder.encode(value); i32(bytes.length); u8.set(bytes, pos); pos += bytes.length; };
  i32(MAGIC); i32(52004); i32(4); i32(nSubcatch); i32(nNodes); i32(nLinks); i32(nPollutants);
  const idPos = pos;
  string('S1'); string('J1'); string('J2'); string('C1');
  const propsPos = pos;
  i32(1); i32(1); f32(1.23);
  i32(3); i32(0); i32(2); i32(3); for (let i=0; i<nNodes*3; i++) f32(i);
  i32(5); i32(0); i32(4); i32(4); i32(3); i32(5); for (let i=0; i<nLinks*5; i++) f32(i);
  for (const n of [8,6,5,15]) { i32(n); for (let i=0; i<n; i++) i32(i); }
  f64(40000); i32(300);
  const resultsPos = pos;
  for (let p=0; p<nPeriods; p++) {
    f64(40000 + (p+1)*300/86400);
    for (let k=0;k<8;k++) f32(k+p);
    for (let node=0;node<2;node++) for (let k=0;k<6;k++) f32(10*node + k + p);
    for (let k=0;k<5;k++) f32(100 + p*10 + k);
    for (let k=0;k<15;k++) f32(500+p*10+k);
  }
  i32(idPos); i32(propsPos); i32(resultsPos); i32(nPeriods); i32(0); i32(MAGIC);
  return u8.slice(0,pos);
}
